/*
  Warnings:

  - Made the column `source` on table `IncomeRecord` required. Backfilled below, so this does NOT fail against existing NULL values.

*/
-- Backfill existing NULL-source rows BEFORE adding NOT NULL — Prisma's
-- autogenerated migration does not do this on its own (see the original
-- warning above); without it, this migration fails outright against any
-- database that already has an IncomeRecord with no source.
UPDATE "IncomeRecord" SET "source" = 'General' WHERE "source" IS NULL;

-- AlterTable
ALTER TABLE "IncomeRecord" ALTER COLUMN "source" SET NOT NULL,
ALTER COLUMN "source" SET DEFAULT 'General';
